# Aliases mapping alternative names to canonical keys
ALIASES: dict[str, str] = {
    "py": "python",
    "js": "javascript",
    "ts": "typescript",
    "rb": "ruby",
    "rs": "rust",
    "golang": "go",
    "cpp": "c++",
    "cplusplus": "c++",
    "cs": "c#",
    "csharp": "c#",
    "c-sharp": "c#",
    "sh": "shell",
    "bash": "shell",
    "zsh": "shell",
    "fish": "shell",
    "shellscript": "shell",
    "powershell": "powershell",
    "pwsh": "powershell",
    "ps1": "powershell",
    "plpgsql": "postgresql",
    "postgres": "postgresql",
    "mysql": "mysql",
    "sqlite": "sqlite",
    "tsql": "sql",
    "asm": "assembly",
    "nasm": "assembly",
    "wasm": "webassembly",
    "jupyter": "jupyter notebook",
    "ipynb": "jupyter notebook",
    "docker": "dockerfile",
    "md": "markdown",
    "mdx": "markdown",
    "latex": "tex",
    "htm": "html",
    "xhtml": "html",
    "scss": "css",
    "sass": "css",
    "less": "css",
    "objc": "objective-c",
    "obj-c": "objective-c",
    "fsharp": "f#",
    "fs": "f#",
    "ocaml": "ocaml",
    "ml": "ocaml",
    "octave": "matlab",
    "vuedotjs": "vue",
    "reactjs": "react",
    "jsx": "react",
    "tsx": "react",
}


def _normalize(name: str) -> str:
    cleaned = str(name or "").strip().lower()
    return ALIASES.get(cleaned, cleaned)


def abbreviate_language(name: str) -> str:
    """Generate a short 1-3 letter clean abbreviation for unknown languages."""
    cleaned = re.sub(r"[^a-zA-Z0-9+#]", " ", str(name or "")).strip()
    words = cleaned.split()
    if len(words) > 1:
        abbr = "".join(word[0] for word in words)[:3].upper()
    elif len(cleaned) <= 3:
        abbr = cleaned.upper()
    else:
        abbr = cleaned[:2].upper()
    return abbr or "?"


def fallback_logo_markup(name: str) -> str:
    """Visually consistent fallback emblem with clean monospace abbreviation."""
    abbr = html.escape(abbreviate_language(name))
    font_size = "7.5" if len(abbr) >= 3 else "8.5"
    return (
        f'<circle cx="12" cy="12" r="9.5" fill="#ffffff" fill-opacity="0.15" '
        f'stroke="#ffffff" stroke-width="1.1" stroke-opacity="0.55"/>'
        f'<text x="12" y="15.2" text-anchor="middle" font-size="{font_size}" '
        f'font-weight="700" font-family="\'SF Mono\', Monaco, Consolas, monospace" '
        f'letter-spacing="0.5" fill="#ffffff">{abbr}</text>'
    )


def get_planet_logo(language: str, radius: float, color: str = "") -> str:
    """Render the centered language logo or fallback scaled to the planet disc.

    The logo is drawn centered at (0, 0) in the planet's coordinate frame.
    Because the planet motion group does not rotate, the logo stays upright
    at all times throughout the orbit.
    """
    key = _normalize(language)
    markup = LANGUAGE_ICONS.get(key)
    if not markup:
        markup = fallback_logo_markup(language)

    # Size proportional to planet radius
    size = max(3.0, radius * 1.15)
    scale = size / 24.0
    offset = -size / 2.0

    return (
        f'<g class="planet-logo" transform="translate({offset:.2f} {offset:.2f}) '
        f'scale({scale:.4f})">{markup}</g>'
    )
